from collections import deque

def transform(grid):
    h,w=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    seen=set(); regions=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=0 or (r,c) in seen: continue
            q=deque([(r,c)]);seen.add((r,c));region=[]
            while q:
                x,y=q.popleft();region.append((x,y))
                for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0<=a<h and 0<=b<w and grid[a][b]==0 and (a,b) not in seen:
                        seen.add((a,b));q.append((a,b))
            regions.append(region)
    if regions:
        small=min(regions,key=len); large=max(regions,key=len)
        for r,c in small: out[r][c]=7
        for r,c in large: out[r][c]=8
    return out
